#!/usr/bin/env node
/**
 * PreToolUse guard — enforces CLAUDE.md section 11 (Write scope).
 *
 * The project is found from the hook payload's cwd (bin/lib/paths.mjs). While the cwd
 * is inside a project, agents may write only to:
 *   mode new       the project folder (~/testharness-projects/<slug>/), except its
 *                  .claude/, CLAUDE.md, reports/ and spec/decisions.json, which stay
 *                  read-only (reports/ is generated by script; decisions are a person's)
 *   mode existing  <repo>/qa/ plus the test directories phase 5 recorded in
 *                  project.json -> suite.path; the rest of the repo is read-only
 *   the session scratchpad, for temporary working files
 *
 * Outside any project the guard is inert, so the harness repository stays editable.
 * Exit 2 blocks the tool call and returns stderr to the model.
 *
 * Covers file-writing tools (Write, Edit, NotebookEdit) by inspecting the target
 * path, and shell tools (Bash, PowerShell) by extracting write targets from the
 * command with bin/lib/shell-writes.mjs. Shell coverage is a heuristic over an
 * unbounded grammar and therefore FAILS OPEN: a command that plainly writes but
 * whose target cannot be parsed is allowed and reported as unverified on stderr,
 * because a guard that wedges the session gets switched off and protects nothing.
 * The residual fail-open gap is stated in CLAUDE.md section 11 rather than papered over.
 *
 * KNOWN COVERAGE BOUNDARY. This guard reads command TEXT. It cannot see writes that
 * live inside a script file it was never shown: `python s.py` and
 * `cat s.py | python -` carry no write evidence in the command, so the resolver
 * finds no target AND the fail-open detector finds no inline write. Those get
 * neither a block nor a warning. Closing it would need syscall tracing rather than
 * command parsing.
 *
 * Scratchpad handling, and why it is anchored. The permitted scratchpad is the
 * session directory under the OS temp root, or an explicit CLAUDE_SCRATCHPAD_DIR.
 * It is NOT "any path containing a segment called scratchpad": that would let
 * `.claude/skills/scratchpad/SKILL.md` through and turn a file-scope escape into
 * instruction injection.
 *
 * One project per folder means no cross-project isolation problem, and no shared state
 * file: scope is a function of the payload cwd (or TESTHARNESS_PROJECT_DIR) alone.
 */
import { resolve, relative, isAbsolute, join } from 'node:path';
import { tmpdir } from 'node:os';
import writeTargets from '../../bin/lib/shell-writes.mjs';
import { findProject, suiteDir, isInside } from '../../bin/lib/paths.mjs';
import { REL } from '../../bin/lib/layout.mjs';

const readStdin = async () => {
  const chunks = [];
  for await (const chunk of process.stdin) chunks.push(chunk);
  return Buffer.concat(chunks).toString('utf8');
};

const allow = (note) => {
  if (note) process.stderr.write(note);
  process.exit(0);
};

const block = (reason) => {
  process.stderr.write(reason);
  process.exit(2);
};

let payload;
try {
  payload = JSON.parse((await readStdin()) || '{}');
} catch {
  allow(); // never let a malformed payload wedge the session
}

const input = payload.tool_input || {};
const base = payload.cwd && isAbsolute(String(payload.cwd)) ? String(payload.cwd) : process.cwd();

// The project is whatever contains the cwd. No project, no scope: the guard is inert,
// so the harness repository itself stays editable.
const project = findProject(base);
if (!project) allow();

/**
 * Case-insensitive comparison on the case-insensitive platforms (Windows, macOS),
 * because `Tests/x` and `tests/x` are the same directory there.
 */
const fold = (p) => (process.platform === 'linux' ? p : p.toLowerCase());
const within = (root, abs) => isInside(fold(resolve(root)), fold(abs));

/** Roots an agent may write to. `new`: the whole project folder (the suite is inside it).
 *  `existing`: the qa/ folder plus the suite directory phase 5 recorded; the rest of the
 *  repo is read-only. */
const writeRoots = [project.dir, ...(project.mode === 'existing' && suiteDir(project) ? [suiteDir(project)] : [])];

/** Read-only inside the writable area: harness configuration, because an agent that can
 *  edit its own rules can lift its own scope, and reports/, which scripts generate from
 *  the registry and the latest run so that no agent can write a number into one. Scripts
 *  run as subprocesses and are not seen by this hook, so they still write there. */
const protectedPaths = [join(project.dir, '.claude'), join(project.dir, 'CLAUDE.md'), join(project.dir, REL.reports), join(project.dir, REL.decisions)];

const describeScope = `project "${project.slug ?? project.dir}" (${project.mode})`;
const roots = writeRoots.join(', ');

/** Anchored scratchpad roots. A path is temporary only if it sits under one of these. */
const tempRoots = [tmpdir(), process.env.CLAUDE_SCRATCHPAD_DIR].filter(Boolean).map((d) => resolve(d));
const inTempRoot = (abs) => tempRoots.some((r) => isInside(r, abs));

/**
 * Verdict for one absolute path: 'allow', or a reason string describing the breach.
 */
function verdict(abs) {
  if (inTempRoot(abs)) return 'allow';
  if (protectedPaths.some((p) => within(p, abs))) return 'read-only while a project is in scope (harness configuration, reports/ which scripts generate, or spec/decisions.json which a person answers)';
  if (writeRoots.some((r) => within(r, abs))) return 'allow';
  return 'outside the project write roots';
}

const pathFields = [input.file_path, input.notebook_path, input.path].filter(Boolean);

// --- File-writing tools: the target path is given to us directly. ---
if (pathFields.length) {
  for (const raw of pathFields) {
    const abs = resolve(base, String(raw));
    const v = verdict(abs);
    if (v !== 'allow') {
      block(
        `Write scope violation: ${abs}\n` +
          `${v}, while ${describeScope} is in scope.\n` +
          `CLAUDE.md section 11: agents write only inside ${roots}.\n` +
          `If this write is genuinely required, run Claude Code from outside the project and state why.`
      );
    }
  }
  allow();
}

// --- Shell tools: extract write targets from the command. ---
const command = input.command ?? input.script;
if (!command) allow();

// A hold is answered by a person. An agent may RAISE one (`qa-decisions.mjs ask`), but
// granting or denying one is the approval itself, so an agent that tries is stopped.
// This is a check on the command text: it stops an agent approving itself, and a command
// assembled indirectly would pass. It is a barrier against talking itself into consent,
// not a cryptographic one.
if (/qa-decisions\.mjs['"]?\s+(grant|deny)\b/.test(String(command))) {
  block(
    `Human decision blocked: ${String(command).trim().slice(0, 140)}\n` +
      `Granting or denying a hold is a person's decision (CLAUDE.md section 27); an agent may only raise one with ` +
      `"qa-decisions.mjs ask". Tell the user which decision is pending and what it asks, then stop. ` +
      `They answer it in their own terminal: node bin/qa-decisions.mjs grant|deny <slug> D-n.`
  );
}

let targets = [];
let confident = true;
try {
  ({ targets, confident } = writeTargets(command));
} catch {
  allow(); // extractor failure must never wedge the session
}

for (const raw of targets) {
  const abs = resolve(base, String(raw));
  const v = verdict(abs);
  if (v !== 'allow') {
    block(
      `Write scope violation in a shell command: ${raw}\n` +
        `Resolved to ${abs}, which is ${v}, while ${describeScope} is in scope.\n` +
        `CLAUDE.md section 11: agents write only inside ${roots}.\n` +
        `Re-target the write.`
    );
  }
}

if (!confident) {
  // Two different situations, and collapsing them dilutes the warning. When some
  // targets were parsed they have already been checked against the permitted roots
  // above — a violation would have blocked — so the honest message is that those
  // are fine and an inline script may still write somewhere unseen. Reporting
  // "could not be parsed" there would fire UNVERIFIED on writes that were in fact
  // verified, and a warning that cries wolf stops being read.
  allow(
    targets.length
      ? `Write-scope guard: ${targets.length} target(s) in this command resolved inside ${roots} and are permitted, ` +
          `but it runs an inline script, which may write to paths that do not appear in the command text. ` +
          `Those were NOT checked. If the script writes outside the permitted roots while ${describeScope} is in scope, ` +
          `that is a section 11 violation you are responsible for not committing.\n`
      : `Write-scope guard: this command writes to the filesystem but no target could be parsed, ` +
          `so it was ALLOWED UNVERIFIED while ${describeScope} is in scope. ` +
          `If it writes outside ${roots}, that is a section 11 violation you are responsible for not committing.\n`
  );
}

allow();
